def zigzagLevelOrder(root):
    if not root:
        return []

    result = []
    queue = [root]
    zigzag = False

    while queue:
        level = []
        for i in range(len(queue)):
            node = queue.pop(0)

            if zigzag:
                level.insert(0, node.val)
            else:
                level.append(node.val)

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        result.append(level)
        zigzag = not zigzag

    return result
