int minCandies(vector<int>& ratings) {
    int n = ratings.size();
    vector<int> candies(n, 1);

    // Use a single pass to calculate the candies
    for(int i = 1; i < n; i++) {
        if(ratings[i] > ratings[i-1]) candies[i] = candies[i-1] + 1;
    }

    // Use a single pass to calculate the sum of candies
    int sum = 0;
    for(int candy : candies) sum += candy;

    return sum;
}
