int countArrangement(int n) {
    int res=0;
    vector<bool> visited(n+1,false); 
    helper(n,1,visited,res); 
    return res;
}

void helper(int n, int idx, vector<bool>& visited, int& res) {
    if (idx > n) {
        ++res;
    }

    for(int i=1; i<=n; i++){
        if (!visited[i] && (idx % i == 0 || i % idx == 0)) { 
            visited[i] = true; 
            helper(n, idx+1, visited, res); 
            visited[i] = false; 
        }
    }
}
