using namespace std;

string findContestMatch(int n) {
    vector<string> matches(n);
    for (int i = 1; i <= n; i++) {
        matches[i - 1] = to_string(i);
    }

    while (n > 1) {
        for (int i = 0; i < n / 2; i++) {
            matches[i] = "(" + matches[i] + "," + matches[n - 1 - i] + ")";
        }
        n /= 2;
    }

    // Improved: Use a single string to store the result
    string result = matches[0];
    for (int i = 1; i < n; i++) {
        result += "," + matches[i];
    }
    return result;
}
