double findMaxAverage(vector<int>& nums, int k) {
    int n = nums.size();
    double sum = 0;
    for (int i = 0; i < k; ++i) {
        sum += nums[i];
    }
    double max_avg = sum / k;
    for (int i = k; i < n; ++i) {
        sum = sum - nums[i - k] + nums[i];
        max_avg = max(max_avg, sum / k);
    }
    return max_avg;
}
