    std::vector<std::vector<int>> memo(n, std::vector<int>(n + 1, 0));

    for (int i = n - 2; i >= 0; --i) {
        piles[i] += piles[i + 1];
    }

    function<int(int, int)> search = [&](int idx, int M) {
        if (idx + 2 * M >= n) {
            return piles[idx];
        }
        if (memo[idx][M] > 0) {
            return memo[idx][M];
        }
        memo[idx][M] = 0;
        for (int x = 1; x <= 2 * M; ++x) {
            memo[idx][M] = std::max(memo[idx][M], piles[idx] - search(idx + x, std::max(M, x)));
        }
        return memo[idx][M];
    };

    return search(0, 1);
}
