#include <unordered_set>
using namespace std;

bool uniqueOccurrences(vector<int>& arr) {
    map<int, int> counts;
    for (int num : arr) {
        counts[num]++;
    }

    unordered_set<int> unique_counts;
    for (auto& count : counts) {
        if (unique_counts.count(count.second) > 0) {
            return false;
        }
        unique_counts.insert(count.second);
    }

    return true;
}
