#include <algorithm>
#include <vector>
using std::max;
using std::vector;

class TreeNode {
public:
    int val;
    TreeNode* left;
    TreeNode* right;
};

class Solution {
    int sumSubtrees(TreeNode* root, vector<int>& sums) {
        if (!root) return 0;
        int sum = root->val + sumSubtrees(root->left, sums) + sumSubtrees(root->right, sums);
        sums.push_back(sum);
        return sum;
    }

public:
    int maxProduct(TreeNode* root) {
        vector<int> sums;
        long long total = sumSubtrees(root, sums);
        long long max_product = 0;

        for (long long sum : sums) {
            max_product = max(max_product, sum * (total - sum));
        }

        return max_product % 1000000007;
    }
};
