    int max_freq = 1, n = nums.size();
    long long sum = 0;
    for (int i = 0, j = 0; j < n; ++j) {
        sum += nums[j];
        while (sum < static_cast<long long>(nums[j]) * (j - i + 1) - k) {
            sum -= nums[i++];
        }
        max_freq = max(max_freq, j - i + 1);
    }
    return max_freq;
}

// Test case
