    int i = 0, j = 0, maxDist = 0;
    while (i < nums1.size() && j < nums2.size()) {
        if (i <= j && nums1[i] <= nums2[j]) {
            maxDist = max(maxDist, j - i);
            j++;
        } else {
            i++;
        }
    }
    return maxDist;
}
