#include <vector>
#include <algorithm>

int maxInvited(const std::vector<int>& favorite) {
    std::vector<int> in_degree(favorite.size(), 0);
    for (int fav : favorite) {
        in_degree[fav]++;
    }
    int result = 0;
    for (int degree : in_degree) {
