def minimumCapability(nums, k):
    n, l, r = len(nums), 1, 10**9
    while l < r:
        mid = l + (r - l) // 2
        i, cnt = 0, 0
        for j in range(n):
            if nums[j] <= mid:
                cnt += 1
                i = j + 2
                while i + 1 < n and (i == j + 1 or nums[i] > mid):
                    i += 1
        if cnt < k:
            l = mid + 1
        else:
            r = mid
    return l
