function solveA() {
  const [n, m] = readLine().split(' ').map(Number);
  const tbl = Array.from({ length: n }, () => Array(m).fill(false));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      const v = Number(readLine());
      tbl[i][j] = v !== 0;
    }
  }
  let corner = false;
  if (tbl[0][0] || tbl[0][m - 1] || tbl[n - 1][0] || tbl[n - 1][m - 1])
    corner = true;
  if (corner) {
    console.log(1);
    return 0;
  }
  let side = false;
  for (let j = 0; j < m; j++) {
    if (tbl[0][j] || tbl[n - 1][j])
      side = true;
  }
  if (!side) {
    for (let i = 0; i < n; i++) {
      if (tbl[i][0] || tbl[i][m - 1])
        side = true;
    }
  }
  if (side) {
    console.log(2);
    return 0;
  }
  console.log(4);
  return 0;
}

function readLine() {
  return require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
  }).readLine();
}

